    const string Progress="/api/membership/research-progress";
    static Task<T> ProgressGet<T>(SubmissionFixture f,string path)=>ReviewGet<T>(f.Server,Progress+path);
    static async Task<OrganizationOpportunitySnapshot> ProgressCard(SubmissionFixture f,OrganizationOpportunitySnapshot parent,string name,OrganizationClaimPolicy? policy=null)
    {
        var draft=await f.Server.Post($"/api/organization/opportunities/campaigns/{parent.CampaignId}",new OrganizationOpportunityRequest(1,Guid.NewGuid(),0,parent.CampaignRevision,name,"Published member summary","Investigate the selected original evidence","No unrelated private evidence",policy??parent.Policy));
        return (await f.Server.Post($"/api/organization/opportunities/{draft.GetProperty("id").GetGuid()}/publish",new OrganizationPublishRequest(1,Guid.NewGuid(),1))).Deserialize<OrganizationOpportunitySnapshot>(WireJson.Options)!;
    }
    static async Task<HttpClient> ProgressPilot(SubmissionFixture f,string name)
    {
        var invite=(await f.Server.Post("/api/organization/members/invitations",new OrganizationInvitationRequest(1,Guid.NewGuid()))).Deserialize<OrganizationInvitationView>(WireJson.Options)!;
        var browser=new HttpClient(new HttpClientHandler{UseCookies=true,AllowAutoRedirect=false}){BaseAddress=new(f.Server.Origin)};
        using(var enroll=await ReviewSend(f.Server,"/api/enrollment",new OrganizationJoinRequest(1,(await ReviewGet<OrganizationPublicIdentity>(f.Server,"/api/public/organization")).Id,name,"ResearchOnly!2026Flight",new Uri(invite.Link!).Fragment[6..],"Scientific research",true),browser))Assert.True(enroll.IsSuccessStatusCode,await enroll.Content.ReadAsStringAsync());
        using(var login=await ReviewSend(f.Server,"/api/sign-in",new OrganizationLoginRequest(name,"ResearchOnly!2026Flight"),browser))Assert.True(login.IsSuccessStatusCode,await login.Content.ReadAsStringAsync());return browser;
    }
    [PostgresFact] public async Task CampaignIndependentPilotsDoNotCountRepeatsPendingOrOldRevisionsAndMemberViewsNeverExposeRawPackages()
    {
        await using var f=await SubmissionFixture.Create();var original=await RealOpportunity(f.Server,ObservationResearch.Template);var policy=new OrganizationClaimPolicy(OrganizationParticipation.MultiPilot,3,3,true,[OrganizationRoles.Administrator,OrganizationRoles.Pilot],"Every required finding must be approved");var card=await ProgressCard(f,original,"Three independent atmospheric observers",policy);var path="/campaigns/"+card.CampaignId;
        using var a=await ProgressPilot(f,"pilot-a");using var b=await ProgressPilot(f,"pilot-b");var servers=new[]{f.Server,new Server(f.Server.App,a,f.Server.Origin,f.Database),new Server(f.Server.App,b,f.Server.Origin,f.Database)};var rows=new List<SubmissionDraft>();var claims=new List<OrganizationClaimView>();var prepared=new List<PreparedOrganizationMission>();
        using var delivery=f.Delivery();
        foreach(var server in servers){var claim=await BrowserClaim(server,card);claims.Add(claim);var upload=server==f.Server?f.Upload:await Connect(f.Desktop,server,OrganizationDesktopPermission.SubmitEvidence);var read=server==f.Server?f.Read:upload;var plan=await f.Desktop.PreviewMission(read,claim.Id,new(),f.Store,default);var saved=await f.Desktop.PrepareMission(read,claim.Id,MissionSave(plan),f.Store,default);prepared.Add(saved);var attempt=await f.Record(saved,3,notes:true);var row=f.Store.SaveSubmissionDraft(new(1,Guid.NewGuid(),0,attempt.FlightId,[attempt.Id],null,"Independent approved contribution",upload),f.Science);await f.Desktop.RefreshSubmissionPolicies(upload,row,f.Store,default);row=f.Store.SaveSubmissionDraft(MissionStore.SubmissionRequest(row),f.Science);var preview=f.Store.PreviewSavedSubmission(row.Id,f.Science);await f.Desktop.ApproveSubmission(row.Id,new(1,row.Revision,preview.ManifestSha256,preview.PayloadSha256,preview.PayloadBytes,upload,true),f.Store,f.Science,default);rows.Add(await delivery.Send(row.Id,default));}
        for(var i=0;i<2;i++)await ReviewCommand(f,rows[i],ResearchReviewAction.Approve,"The received original documentation fulfills this card, not a numerical hypothesis.",new(prepared[i].Card.Id,"documentation"),[new(rows[i].Receipt!.Id,"*")]);
        var view=Assert.Single((await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Three&sort=remaining")).Items);Assert.Equal(2,view.ApprovedDistinctPilots);Assert.Equal(3,view.RequiredDistinctPilots);Assert.Equal(1,view.AwaitingReview);Assert.Equal(CampaignWorkState.PartiallyFulfilled,view.State);Assert.Equal(0,view.AvailableClaims);
        var repeat=await f.Record(prepared[0],3,notes:true);var repeated=await f.ReviewApprove(f.Draft(repeat));repeated=await delivery.Send(repeated.Id,default);await ReviewCommand(f,repeated,ResearchReviewAction.Approve,"A repeated contribution from the same pilot counts only once.",new(prepared[0].Card.Id,"documentation"),[new(repeated.Receipt!.Id,"*")]);Assert.Equal(2,(await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Three")).Items.Single().ApprovedDistinctPilots);
        var summaries=await a.GetFromJsonAsync<OrganizationPage<ApprovedResearchSummary>>(Progress+path+"/approved",WireJson.Options);Assert.Equal(3,summaries!.Items.Length);Assert.Equal(2,summaries.Items.Select(s=>s.Contributor).Distinct().Count());Assert.Single(summaries.Items,s=>s.IsOwnContribution);foreach(var item in summaries.Items){using var allowed=await a.GetAsync(Progress+$"/approved/{item.RootReceiptId}/{item.CardId}");Assert.Equal(HttpStatusCode.OK,allowed.StatusCode);using var privatePackage=await a.GetAsync($"/api/organization/reviews/{item.RootReceiptId}/item?receipt={item.RootReceiptId}&key=x");Assert.Equal(HttpStatusCode.Forbidden,privatePackage.StatusCode);}using(var attention=await a.GetAsync(Progress+path+"/reviews"))Assert.Equal(HttpStatusCode.Forbidden,attention.StatusCode);
        await f.Server.Post("/api/membership/research/claim-command",new OrganizationClaimCommand(1,Guid.NewGuid(),card.OrganizationId,card.Id,card.Revision,OrganizationClaimAction.Release,claims[0].Id,claims[0].Revision));var reclaim=await BrowserClaim(f.Server,card);Assert.NotEqual(claims[0].Id,reclaim.Id);Assert.Equal(2,(await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Three")).Items.Single().ApprovedDistinctPilots);
        var edit=(await f.Server.Post($"/api/organization/opportunities/{card.Id}/campaigns/{card.CampaignId}",new OrganizationOpportunityRequest(1,Guid.NewGuid(),card.Revision,card.CampaignRevision,card.Name,"Updated criteria publication",card.Objective,card.Instructions,policy),HttpMethod.Put)).Deserialize<OrganizationOpportunitySnapshot>(WireJson.Options)!;var updated=(await f.Server.Post($"/api/organization/opportunities/{card.Id}/publish",new OrganizationPublishRequest(1,Guid.NewGuid(),edit.Revision))).Deserialize<OrganizationOpportunitySnapshot>(WireJson.Options)!;
        Assert.Equal(0,(await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Three")).Items.Single().ApprovedDistinctPilots);Assert.Empty((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);var prior=await ProgressGet<CampaignCardDetail>(f,$"/cards/{card.Id}?revision={card.Revision}");Assert.Equal(2,prior.Card.ApprovedDistinctPilots);Assert.Contains(prior.Versions.Items,v=>v.PublicationRevision==updated.Revision&&v.Current);Assert.Equal(3,(await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+$"/approved?opportunity={card.Id}&revision={card.Revision}")).Items.Length);Assert.Empty((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/coverage/groups")).Items);var oldCoverage=Assert.Single((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+$"/coverage/groups?opportunityId={card.Id}&publicationRevision={card.Revision}")).Items);Assert.Equal(2,oldCoverage.Pilots);Assert.Equal(3,oldCoverage.Flights);Assert.Equal(9,oldCoverage.Observations);
        var member=(await ReviewGet<OrganizationPage<OrganizationMemberView>>(f.Server,"/api/organization/members")).Items.Single(m=>m.Name=="pilot-a");await f.Server.Post("/api/organization/members/"+member.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),member.Revision,member.Role,OrganizationMembershipState.Suspended),HttpMethod.Put);using(var revoked=await a.GetAsync(Progress+path))Assert.Equal(HttpStatusCode.Unauthorized,revoked.StatusCode);using(var revoked=await a.GetAsync(Progress+path+"/coverage/locations"))Assert.Equal(HttpStatusCode.Unauthorized,revoked.StatusCode);Assert.Equal(2,(await ProgressGet<CampaignCardDetail>(f,$"/cards/{card.Id}?revision={card.Revision}")).Card.ApprovedDistinctPilots);
        await f.Restart();Assert.Equal(2,(await ProgressGet<CampaignCardDetail>(f,$"/cards/{card.Id}?revision={card.Revision}")).Card.ApprovedDistinctPilots);
    }
    [PostgresFact] public async Task CampaignProgressPagesPublishedWorkAndReadOnlyDesktopHasNoMutationOrPrivateReviewScopeOffline()
    {
        await using var f=await SubmissionFixture.Create();var card=await RealOpportunity(f.Server,ObservationResearch.Template);for(var i=0;i<21;i++)await ProgressCard(f,card,"Indexed card "+i.ToString("D2"));var path="/campaigns/"+card.CampaignId;
        var first=await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Indexed&sort=name");Assert.Equal(20,first.Items.Length);Assert.Equal(20,first.NextOffset);var last=await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?search=Indexed&offset=20");Assert.Single(last.Items);Assert.Null(last.NextOffset);Assert.Equal(21,first.Items.Concat(last.Items).Select(c=>c.OpportunityId).Distinct().Count());Assert.Empty((await ProgressGet<OrganizationPage<CampaignCardProgress>>(f,path+"/cards?state=CompletedByApprovedEvidence")).Items);
        using(var bad=await f.Server.Browser.GetAsync(Progress+path+"/cards?state=999"))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);using(var missing=await f.Server.Browser.GetAsync(Progress+"/campaigns/"+Guid.NewGuid()))Assert.Equal(HttpStatusCode.NotFound,missing.StatusCode);
        var desktop=await f.Desktop.CampaignProgress(f.Read,card.CampaignId,default);Assert.True(desktop.VerifiedNow);Assert.False(desktop.Value!.CanReview);Assert.False(desktop.Value.CanManage);Assert.Equal(22,desktop.Value.Totals.PublishedCards);Assert.Equal(20,(await f.Desktop.CampaignCards(f.Read,card.CampaignId,0,"Indexed","name","",default)).Value!.Items.Length);Assert.Single((await f.Desktop.ProgramProgress(f.Read,card.ProgramId,0,default)).Value!.Campaigns.Items);
        using var native=new HttpClient{BaseAddress=new(f.Server.Origin)};native.DefaultRequestHeaders.Authorization=new("Bearer",f.Vault.Read(f.Read));using(var denied=await native.GetAsync("/api/member/research-progress"+path+"/reviews"))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);using(var denied=await native.PostAsJsonAsync("/api/member/claim-command",new OrganizationClaimCommand(1,Guid.NewGuid(),card.OrganizationId,card.Id,card.Revision,OrganizationClaimAction.Claim),WireJson.Options))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        await f.Server.App.StopAsync();var offline=await f.Desktop.CampaignProgress(f.Read,card.CampaignId,default);Assert.False(offline.VerifiedNow);Assert.Null(offline.Value);Assert.Contains("Unavailable",offline.Status);Assert.False(File.Exists(Path.Combine(f.Root,"campaign-progress.json")));await f.Restart();Assert.True((await f.Desktop.CampaignProgress(f.Read,card.CampaignId,default)).VerifiedNow);
    }
    [PostgresFact] public async Task ApprovedCampaignCountsOnlyCurrentCompleteIndependentFindingsAndRebuildsWithoutPrivateEvidence()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(ObservationResearch.Template);var path="/campaigns/"+c.Published.CampaignId;
        var initial=await ProgressGet<CampaignProgressView>(f,path);Assert.Equal(1,initial.Totals.PublishedCards);Assert.Equal(0,initial.Totals.ApprovedPilotContributions);
        var recorded=await f.Record(c.Prepared,3,notes:true);var row=await f.ReviewApprove(f.Draft(recorded));using var delivery=f.Delivery();row=await delivery.Send(row.Id,default);var root=row.Receipt!.Id;
        var waiting=await ProgressGet<CampaignProgressView>(f,path);Assert.Equal(1,waiting.Totals.AwaitingReview);Assert.Equal(0,waiting.Totals.CompletedCards);Assert.Empty((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);
        await ReviewCommand(f,row,ResearchReviewAction.Approve,"PRIVATE REVIEWER NOTE",new(c.Prepared.Card.Id,"documentation"),[new(root,"*")]);
        var completed=await ProgressGet<CampaignProgressView>(f,path);Assert.Equal(1,completed.Totals.CompletedCards);Assert.Equal(1,completed.Totals.ApprovedPilotContributions);
        var approved=Assert.Single((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);Assert.True(approved.IsOwnContribution);Assert.StartsWith("Contributor ",approved.Contributor);Assert.Equal(c.Published.Revision,approved.PublicationRevision);Assert.Equal(c.Published.Id,approved.OpportunityId);
        var detail=await ProgressGet<ApprovedResearchDetail>(f,$"/approved/{root}/{approved.CardId}");Assert.Equal(3,detail.Measurements.Items.Sum(m=>m.Count));Assert.All(detail.Measurements.Items,m=>{Assert.Null(m.Minimum);Assert.Null(m.Maximum);Assert.Equal("Pilot Observation",m.Provenance);});
        var json=JsonSerializer.Serialize(detail,WireJson.Options);foreach(var secret in new[]{"Selected original pilot note","PRIVATE REVIEWER NOTE","PRIVATE-CONTEXT-NOT-SHARED",f.Vault.Read(f.Upload)! ,"SYNTHETIC evidence fixture, no MSFS"})Assert.DoesNotContain(secret,json);
        var locations=await ProgressGet<OrganizationPage<ApprovedResearchLocation>>(f,$"/approved/{root}/{approved.CardId}/locations");Assert.Equal(3,locations.Items.Length);Assert.All(locations.Items,p=>{Assert.Equal(40,p.Latitude);Assert.Equal(-75,p.Longitude);});
        // A stale/missing derived head is never permission to publish an old approval.
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();await db.CampaignProjections.Where(p=>p.RootId==root).ExecuteUpdateAsync(s=>s.SetProperty(p=>p.ReviewRevision,0));}
        Assert.Equal(1,(await ProgressGet<CampaignProgressView>(f,path)).Totals.UnavailableReviews);Assert.Empty((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);
        using(var scope=f.Server.App.Services.CreateScope()){await scope.ServiceProvider.GetRequiredService<CampaignProgressProjection>().Sync(root,default,true);}
        // Repeated reads, unrelated comments and a forced rebuild neither add contributors nor re-date acceptance.
        await ReviewCommand(f,row,ResearchReviewAction.Comment,"Unrelated private method discussion");
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();await using var tx=await db.Database.BeginTransactionAsync();await scope.ServiceProvider.GetRequiredService<CampaignProgressProjection>().Sync(root,default,true);await tx.CommitAsync();}
        await f.Restart();var reopened=Assert.Single((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);Assert.Equal(approved.AcceptedUtc,reopened.AcceptedUtc);Assert.Equal(1,(await ProgressGet<CampaignProgressView>(f,path)).Totals.ApprovedPilotContributions);
        await f.Server.Post("/api/membership/research/claim-command",new OrganizationClaimCommand(1,Guid.NewGuid(),c.Published.OrganizationId,c.Published.Id,c.Claim.IssuedRevision,OrganizationClaimAction.Release,c.Claim.Id,c.Claim.Revision));Assert.Equal(1,(await ProgressGet<CampaignProgressView>(f,path)).Totals.CompletedCards);
        await ReviewCommand(f,row,ResearchReviewAction.Reject,"A later authorized finding supersedes the current approval without changing the original notes.",new(c.Prepared.Card.Id,"documentation"));Assert.Empty((await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved")).Items);Assert.Equal(0,(await ProgressGet<CampaignProgressView>(f,path)).Totals.CompletedCards);using var hidden=await f.Server.Browser.GetAsync(Progress+$"/approved/{root}/{approved.CardId}");Assert.Equal(HttpStatusCode.NotFound,hidden.StatusCode);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,f.Store.ResearchAttempt(recorded.Id).Outcome);
    }
    [PostgresFact] public async Task ApprovedAtmosphericSummaryPreservesOriginalNumbersUnitsDatesAndOnlySupportedLocations()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(AtmosphericResearch.Template);var result=await AtmosphericRecording(f,c.Prepared);var row=await f.ReviewApprove(f.Draft(result));var original=f.Store.ApprovedSubmissionDocument(row.Id,f.Science).Evidence.SelectMany(i=>i.Data.Observations??[]).ToArray();using var delivery=f.Delivery();row=await delivery.Send(row.Id,default);var root=row.Receipt!.Id;var snap=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));
        foreach(var q in snap.Requirements)await ReviewCommand(f,row,ResearchReviewAction.Approve,"Supported original atmospheric collection, not proof of an atmospheric hypothesis.",new(q.Requirement.CardId,q.Requirement.Key),[new(root,"*")]);
        var detail=await ProgressGet<ApprovedResearchDetail>(f,$"/approved/{root}/{c.Prepared.Card.Id}");var measure=Assert.Single(detail.Measurements.Items);Assert.Equal(original.Length,measure.Count);Assert.Equal(original.Min(o=>o.Value),measure.Minimum);Assert.Equal(original.Max(o=>o.Value),measure.Maximum);Assert.Equal(original.First().Unit,measure.Unit);Assert.Equal(original.Min(o=>o.AltitudeMslFeet),measure.MinimumAltitudeFeetMsl);Assert.Equal(original.Max(o=>o.AltitudeMslFeet),measure.MaximumAltitudeFeetMsl);Assert.Equal(original.Min(o=>o.TimestampUtc),measure.StartUtc);Assert.Contains("Synthetic",measure.SourceCategory);Assert.All((await ProgressGet<OrganizationPage<ApprovedResearchLocation>>(f,$"/approved/{root}/{c.Prepared.Card.Id}/locations")).Items,p=>Assert.Contains(original,o=>o.TimestampUtc==p.TimestampUtc&&o.Latitude==p.Latitude&&o.Longitude==p.Longitude));
    }
    [PostgresFact] public async Task ApprovedInventoryPagesAndRebuildsFromOriginalReceiptsWithoutTurningManySubmissionsIntoManyPilots()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(ObservationResearch.Template);var result=await f.Record(c.Prepared,3,notes:true);var local=await f.ReviewApprove(f.Draft(result));var original=f.Store.ApprovedSubmissionDocument(local.Id,f.Science);using var delivery=f.Delivery();local=await delivery.Send(local.Id,default);
        // Scale fixture inserts independently hashed retained P17 originals through its metadata services;
        // it does not weaken the production six-per-minute transfer limit or invent pilot identities.
        for(var i=0;i<20;i++){
            using var scope=f.Server.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();var doc=original with{Manifest=original.Manifest with{Id=Guid.NewGuid(),Name="Paged accepted summary "+i}};var bytes=SubmissionEvidenceProtocol.Bytes(doc);var receipt=new SubmissionReceipt(1,Guid.NewGuid(),doc.Manifest.Id,doc.Manifest.OrganizationId,doc.Manifest.PilotId,doc.Manifest.CampaignId,PreflightReadiness.Hash(doc.Manifest),PreflightReadiness.Hash(doc),bytes,DateTimeOffset.UtcNow,"Received / Awaiting Review",SubmissionEvidenceProtocol.RetentionDisclosure);
            await using var tx=await db.Database.BeginTransactionAsync();db.Submissions.Add(new(){Id=doc.Manifest.Id,PilotId=doc.Manifest.PilotId,ReceiptId=receipt.Id,CampaignId=doc.Manifest.CampaignId,Name=doc.Manifest.Name,SearchName=doc.Manifest.Name.ToUpperInvariant(),ManifestSha256=receipt.ManifestSha256,PayloadSha256=receipt.PayloadSha256,PayloadBytes=bytes,PayloadJson=JsonSerializer.Serialize(doc,WireJson.Options),ReceiptJson=JsonSerializer.Serialize(receipt,WireJson.Options),ReceivedUtc=receipt.ReceivedUtc});await scope.ServiceProvider.GetRequiredService<OrganizationReviews>().Received(doc,receipt,default);await db.SaveChangesAsync();await tx.CommitAsync();
        }
        // Missing derived indexes are recoverable on a real process restart; originals remain untouched.
        await f.Restart();var first=await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews");var second=await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews?offset=20");foreach(var item in first.Items.Concat(second.Items)){var review=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(item.RootReceiptId));await f.Server.Post(ReviewPath(item.RootReceiptId)+"/commands",new ResearchReviewCommand(1,Guid.NewGuid(),review.Summary.Revision,ResearchReviewAction.Approve,new(c.Prepared.Card.Id,"documentation"),Evidence:[new(item.RootReceiptId,"*")],ConfirmApproval:true));}
        var path="/campaigns/"+c.Published.CampaignId;var page=await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved?sort=newest");Assert.Equal(20,page.Items.Length);Assert.Equal(20,page.NextOffset);var last=await ProgressGet<OrganizationPage<ApprovedResearchSummary>>(f,path+"/approved?sort=newest&offset=20");Assert.Single(last.Items);Assert.Null(last.NextOffset);Assert.Equal(21,page.Items.Concat(last.Items).Select(s=>s.RootReceiptId).Distinct().Count());Assert.Single(page.Items.Concat(last.Items).Select(s=>s.Contributor).Distinct());Assert.Equal(1,(await ProgressGet<CampaignProgressView>(f,path)).Totals.ApprovedPilotContributions);Assert.Equal(21,(await ProgressGet<CampaignProgressView>(f,path)).Totals.ReceivedCards);var coverage=Assert.Single((await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/coverage/groups")).Items);Assert.Equal(3,coverage.Observations);Assert.Equal(1,coverage.Pilots);Assert.Equal(60,coverage.DuplicateReferences);Assert.Equal(3,(await ProgressGet<OrganizationPage<CoverageLocation>>(f,path+"/coverage/locations")).Items.Length);
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();var source=await db.Submissions.SingleAsync(s=>s.ReceiptId==local.Receipt!.Id);Assert.Equal(PreflightReadiness.Hash(original),source.PayloadSha256);}
    }
